export derive can_work(person:user,location:Location):bool = any(Employee as e,e.user==person and e.active and active_member(person,team) and (e.operator_wide or e.home==location or location in e.locations))
scenario reserve(booking:Booking,table:Table,from:datetime,until:datetime) by=host
require can_work(actor,booking.parent.location) and booking.state==waiting and table.parent==booking.parent and booking.party<=table.seats and from<until and available(table,from,until,booking)
